  async dashboardEmailReply(input:import("./email/types.js").EmailReplyInput){await this.ensureConnections();if(!input||typeof input.connectionId!=="string"||typeof input.messageId!=="string"||typeof input.bodyText!=="string")throw new Error("Dados da resposta inválidos.");return this.agent.runPlan("Responder e-mail pelo Dashboard",[{tool:"email_reply",input}]);}
  async dashboardEmailTrash(input:{connectionId:string;messageId:string}){await this.ensureConnections();if(!input||typeof input.connectionId!=="string"||!input.connectionId.trim()||typeof input.messageId!=="string"||!input.messageId.trim())throw new Error("Dados de exclusão inválidos.");return this.agent.runPlan("Mover e-mail para a lixeira pelo Dashboard",[{tool:"email_trash",input:{connectionId:input.connectionId.trim(),messageId:input.messageId.trim()}}]);}
  async getEmailSearchPreferences(connectionId:string){
    await this.ensureConnections();
    const account=this.connections.get(connectionId);
    if(!account)throw new Error("Conexão não encontrada.");
    const saved=this.agentRuntime.emailPreferences.get(connectionId);
    const options=getMailboxOptions(account.provider);
    const categories=saved?.categories??defaultMailboxCategories(account.provider);
    return{connectionId,provider:account.provider,categories,options};
  }
  async saveEmailSearchPreferences(connectionId:string,categories:string[]){
    await this.ensureConnections();
    const account=this.connections.get(connectionId);
    if(!account)throw new Error("Conexão não encontrada.");
    const normalized=normalizeMailboxCategories(account.provider,categories);
    const result=this.agentRuntime.emailPreferences.save(connectionId,normalized);
    await this.dashboardRefresh("email");
    return result;
  }
  async dashboardRefresh(gadgetId:DashboardGadgetId,configuration:Record<string,unknown>={}){await this.ready();const row=this.db.get<{cache_key:string}>("SELECT cache_key FROM dashboard_cache WHERE provider=?",[gadgetId]);if(row)this.db.run("DELETE FROM dashboard_cache WHERE provider=? AND cache_key=?",[gadgetId,this.dashboardCacheKey(gadgetId,configuration)]);return this.dashboard.data(gadgetId,configuration);}
  private dashboardCacheKey(gadgetId:DashboardGadgetId,configuration:Record<string,unknown>){return gadgetId==="weather"?`${configuration.latitude},${configuration.longitude},${configuration.unit??"C"}`:gadgetId==="currency"?String(configuration.currencies??"USD,EUR,GBP,JPY"):gadgetId;}
  private async dashboardInternalData(id:DashboardGadgetId):Promise<unknown>{
    if(id==="ai-status"){const status=await this.llm.health();return{connected:status.ok,detail:status.detail,model:this.settings.model,autonomy:this.settings.autonomy,privateMode:this.settings.privateMode,toolCount:this.tools.list().filter(tool=>this.security.isToolEnabled(tool.name)).length};}
    if(id==="tasks")return this.tasks.listActive().filter(task=>task.type==="assistant-chat").map(task=>({id:task.id,title:String(task.input.text??"Tarefa do Nexo"),status:task.status,progress:task.statusMessage,startedAt:task.startedAt}));
    if(id==="approvals")return this.approvals.list().filter(item=>item.status==="pending").slice(0,8).map(item=>({id:item.id,toolName:item.toolName,reason:item.reason,createdAt:item.createdAt}));
    if(id==="automations"){const all=this.macros.list(),recent=all.flatMap(macro=>this.macros.listRuns(macro.id,5)).sort((a,b)=>b.startedAt.localeCompare(a.startedAt));return{total:all.length,enabled:all.filter(macro=>macro.enabled).length,recentRuns:recent.slice(0,8)};}
    if(id==="activity")return this.audit.list(200).filter(item=>Date.now()-Date.parse(item.createdAt)<7*86400000).slice(0,50);
    if(id==="documents"){if(this.settings.documentsEnabled===false)return[];await this.ensureDocuments();return this.documents.listRecent().slice(0,8);}
    if(id==="system"){const reply=await this.agent.execute("daily_summary",{}, {runId:"dashboard-system-gadget"});if(!reply.result?.ok)throw new Error(typeof reply.result?.error==="string"?reply.result.error:reply.result?.error?.message??reply.text);return reply.result.data;}
    if(id==="email"){if(!this.settings.connectionsEnabled)return{available:false,unreadCount:0,messages:[]};await this.ensureConnections();const connection=this.connections.defaultFor("email.read");if(!connection)return{available:false,unreadCount:0,messages:[]};const [stats,result]=await Promise.all([this.email.stats(connection.id),this.email.search({connectionId:connection.id,maxResults:5})]);return{available:true,connectionId:connection.id,provider:connection.provider,canModify:connection.capabilities.includes("email.modify"),unreadCount:stats.unreadMessages??0,messages:result.messages.slice(0,5).map(message=>({id:message.id,threadId:message.threadId,from:message.from,subject:message.subject,snippet:message.snippet??"",receivedAt:message.receivedAt,isUnread:Boolean(message.isUnread),hasAttachments:Boolean(message.hasAttachments)}))};}
    if(id==="agenda"){if(!this.settings.connectionsEnabled)return{available:false,events:[]};await this.ensureConnections();const connection=this.connections.defaultFor("calendar.read");if(!connection)return{available:false,events:[]};const start=new Date();start.setHours(0,0,0,0);const end=new Date(start);end.setDate(end.getDate()+1);const events=await this.calendar.list(connection.id,start.toISOString(),end.toISOString());events.sort((a,b)=>Number(Boolean(b.allDay))-Number(Boolean(a.allDay))||Date.parse(a.start)-Date.parse(b.start));return{available:true,connectionId:connection.id,events:events.map(event=>({id:event.id,title:event.title,start:event.start,end:event.end,allDay:Boolean(event.allDay),location:event.location,meetingUrl:event.meetingUrl}))};}
    return null;
  }
  private syncDashboardConnections(){if(!this.settings.connectionsEnabled||!this.connections)return;const capabilities=new Set(this.connections.list().filter(item=>item.status==="connected"||item.status==="degraded").flatMap(item=>item.capabilities));this.dashboard.syncConnectedGadgets(capabilities);}

