  async resolveInlineApproval(conversationId:string,messageId:string,approvalId:string,approved:boolean){
    await this.ready();
    const message=this.conversations.getMessage(conversationId,messageId);
    if(!message?.blocks?.some(block=>block.type==="approval"&&block.approvalId===approvalId))throw new Error("Aprovação não pertence à mensagem.");
    try{return await this.approve(approvalId,approved);}finally{
      const record=this.conversations.presentationRecordForMessage(messageId),approval=this.approvals.list("all").find(item=>item.id===approvalId);
      if(record&&approval){for(const block of record.presentation.blocks)if(block.type==="approval"&&block.approvalId===approvalId)block.status=approval.status;this.conversations.savePresentation(messageId,record);}
    }
  }
