  async status(){await this.ready();const lastExecution=this.db.get<{tool_name:string;status:string;error:string|null}>("SELECT tool_name,status,error FROM execution_records ORDER BY created_at DESC LIMIT 1"),lastFallback=this.metrics.latest("agent.legacy_fallback");return{llm:await this.llm.health(),models:await this.llm.models(),settings:this.getSettings(),tools:this.tools.list().map(tool=>({...tool,enabled:this.security.isToolEnabled(tool.name)})),metrics:this.metrics.snapshot(),agents:this.agentPool.snapshot(),resources:this.resources.snapshot(),agentDiagnostics:{engine:this.settings.forceLegacyAgent?"legacy":this.settings.agentLoopMode??"full",model:this.settings.model,lastFallback,lastTool:lastExecution?.tool_name,lastFailure:lastExecution?.error,pendingApprovals:this.approvals.list().filter(item=>item.status==="pending").length,recoverableRuns:this.db.get<{count:number}>("SELECT COUNT(*) count FROM agent_runs WHERE engine_version='agent-loop-v2' AND status NOT IN ('COMPLETED','FAILED','CANCELLED')")?.count??0,resultUnknown:this.db.get<{count:number}>("SELECT COUNT(*) count FROM execution_records WHERE status IN ('RESULT_UNKNOWN','UNRESOLVED')")?.count??0,reconciliationStatus:lastExecution?.status,hybridIntent:this.commandService.hybridDiagnostics(),decisionTrace:this.commandService.decisionTrace(Boolean(this.settings.developerDiagnosticsEnabled))}};}
  async draftMacro(description:string,name?:string):Promise<GeneratedMacroDraft>{await this.ready();const request=description.trim();if(request.length<8||request.length>3000)throw new Error("Descreva a macro em 8 a 3000 caracteres.");const catalog=this.macros.actionCatalog().filter(item=>["system.open_application","filesystem.open_path","filesystem.copy","filesystem.rename","filesystem.create_folder","filesystem.move","browser.open_url","browser.download","web.search","web.fetch","system.wait","filesystem.list","system.snapshot","browser.open","browser.extract","ai.summarize","ai.classify","notification.show"].includes(item.id));const compact=catalog.map(item=>({id:item.id,title:item.title,fields:item.fields.map(field=>({key:field.key,type:field.type,required:field.required,options:field.options?.map(option=>option.value)}))}));const raw=await this.llm.plan([{role:"system",content:`Converta a descrição em uma macro executável. Responda somente JSON: {"name":string,"actions":[{"type":string,"config":object}]}. Use apenas action IDs deste catálogo e os campos indicados. Não invente ações, caminhos, URLs, aplicativos nem valores ausentes; se faltar um dado indispensável, use string vazia para que o usuário o complete. Máximo 20 etapas. O usuário revisará antes de salvar. Catálogo: ${JSON.stringify(compact)}`},{role:"user",content:`Nome sugerido: ${name?.trim()||"(gere um nome curto)"}\nDescrição: ${request}`}]);return normalizeMacroDraft(raw,request,name,catalog);}
